package org.sleepwell.app;
import java.util.function.*;
/** Serial-worker-only monotone brightness ramp. Restore is conditional, never a global lamp reset. */
final class HueBridgeRun implements AutoCloseable {
 private final HueBridgeConfig config;private final BooleanSupplier live,restoreAllowed;private final Consumer<String> status;private final HueBridgeApi api;private HueBridgeApi.State original;private int last;private boolean touched,closed,relinquished;private long tick=Long.MIN_VALUE;
 HueBridgeRun(HueBridgeConfig config,BooleanSupplier live,BooleanSupplier restoreAllowed,Consumer<String> status){this.config=config;this.live=live;this.restoreAllowed=restoreAllowed;this.status=status;api=new HueBridgeApi(config,()->live.getAsBoolean()||closed&&restoreAllowed.getAsBoolean());}
 private boolean same(HueBridgeApi.State state,int brightness){return state.on&&Math.abs(state.brightness-brightness)<=1&&state.unchanged.equals(original.unchanged);}
 void tick(long elapsed){if(closed||relinquished)return;if(!live.getAsBoolean()){close();return;}if(tick!=Long.MIN_VALUE&&elapsed-tick<5000)return;tick=elapsed;try{if(original==null){config.validate();original=api.read();last=original.brightness;if(original.on&&original.brightness>=Math.round(config.maximum*254f/100)){relinquished=true;status.accept("Selected Hue light is already above the target; unchanged.");return;}}
  int minimum=original.on?original.brightness:1,maximum=Math.max(minimum,Math.round(config.maximum*254f/100));double amount=Math.max(0,Math.min(1,elapsed/(config.minutes*60000d)));int next=Math.max(minimum,Math.min(maximum,(int)Math.round(minimum+(maximum-minimum)*amount)));if(touched&&next<=last)return;HueBridgeApi.State current=api.read();boolean owned=touched?same(current,last):current.on==original.on&&current.brightness==original.brightness&&current.unchanged.equals(original.unchanged);if(!owned){relinquished=true;touched=false;status.accept("Hue light changed elsewhere; this sunrise stopped without restoring over that change.");return;}if(!live.getAsBoolean()){close();return;}last=next;touched=true;api.set(true,next);status.accept(next>=maximum?"Selected Hue sunrise reached its maximum.":"Selected Hue sunrise is active.");
 }catch(Exception unavailable){relinquished=true;status.accept("Hue sunrise unavailable or unconfirmed; the phone alarm continues. Check bridge identity, connection and selected light.");close();}}
 @Override public void close(){if(closed)return;closed=true;try{if(original==null||!touched||!config.restore||!restoreAllowed.getAsBoolean())return;HueBridgeApi.State current=api.read();if(!same(current,last)){status.accept("Hue light ownership changed; its current state was left unchanged.");return;}if(!restoreAllowed.getAsBoolean())return;api.set(original.on,original.brightness);status.accept("Selected Hue light restored to its observed original on/off and brightness state.");}catch(Exception unavailable){status.accept("Hue restoration could not be confirmed. Check the selected light; no automatic retry will run.");}finally{api.close();}}
}
